"""Generators: modulo schedule -> distributed controller (RTL), parameters, HLS tables."""
from __future__ import annotations

from pathlib import Path

from . import schedule
from .schedule import Schedule

BANK_CODE = {"BM": 0, "MM": 1, "OB": 2}
BANK_NAME = {0: "BM", 1: "MM", 2: "OB"}

HEADER = """// ============================================================================
// {name}
// ----------------------------------------------------------------------------
// GENERATED by `python -m dct8 emit` from the exact modulo schedule
// (python/dct8/schedule.py).  Do not edit by hand: change the schedule and
// re-run the generator.
//
// Modulo schedule: period 8 (one sample per clock), CORDIC latency {lat},
// output latency T0 = {t0} (Y0 is read {t0} clocks after x0 entered).
//
{rows}
// ============================================================================
"""


def _fmt_bf(op) -> str:
    if not op:
        return "-"
    return f"{op['op']}({op['ins'][0]},{op['ins'][1]})"


def _rows(sch: Schedule) -> str:
    out = ["//   ph | BF0                | BF1                | CORDIC issue        | CORDIC done | out"]
    for r in sch.table:
        mi = r["mr_issue"]
        mis = f"{mi['op']} k={mi['k']} ({mi['ins'][0]},{mi['ins'][1]})" if mi else "-"
        md = r["mr_done"]["op"] if r["mr_done"] else "-"
        out.append(f"//    {r['phase']} | {_fmt_bf(r['bf'][0]):18s} | {_fmt_bf(r['bf'][1]):18s} | "
                   f"{mis:19s} | {md:11s} | Y{r['out_k']}")
    return "\n".join(out)


def _bf_module(sch: Schedule, unit: int) -> str:
    lines = []
    for r in sch.table:
        op = r["bf"][unit]
        if op is None:
            lines.append(f"            3'd{r['phase']}: ; // idle")
            continue
        (sa, ra), (sb, rb) = op["src"]
        (ds, rs), (dd, rd) = op["dst"]
        a_ib = int(sa == "IB")
        b_in = int(sb == "IN")
        lines.append(
            f"            3'd{r['phase']}: begin  // {op['op']}: ({op['ins'][0]}, {op['ins'][1]})"
            f" -> ({op['outs'][0]}, {op['outs'][1]}), stage {op['stage']}\n"
            f"                en = 1'b1; stage = 2'd{op['stage']};"
            + (f" a_ib = 1'b{a_ib}; b_in = 1'b{b_in};" if unit == 0 else "") +
            f" a_addr = 3'd{ra if ra is not None else 0}; b_addr = 3'd{rb if rb is not None else 0};\n"
            f"                sum_bank = 2'd{BANK_CODE[ds]}; sum_addr = 3'd{rs};"
            f"  diff_bank = 2'd{BANK_CODE[dd]}; diff_addr = 3'd{rd};\n"
            f"            end")
    ports0 = ("    output reg        a_ib,       // operand A from the input buffer (else butterfly buffers)\n"
              "    output reg        b_in,       // operand B is the incoming sample (else butterfly buffers)\n"
              if unit == 0 else "")
    init0 = " a_ib = 1'b0; b_in = 1'b0;" if unit == 0 else ""
    return f"""
// Butterfly datapath BF{unit}: operand sources, SS-unit select, destinations.
module dct8_ctrl_bf{unit} (
    input  wire [2:0] phase,
    output reg        en,         // a butterfly executes this cycle
    output reg  [1:0] stage,      // flow-graph stage 1..3 (selects the SS unit flag)
{ports0}    output reg  [2:0] a_addr,
    output reg  [2:0] b_addr,
    output reg  [1:0] sum_bank,   // 0 butterfly buffers, 1 memory bank, 2 output buffer
    output reg  [2:0] sum_addr,
    output reg  [1:0] diff_bank,
    output reg  [2:0] diff_addr
);
    always @(*) begin
        en = 1'b0; stage = 2'd1;{init0} a_addr = 3'd0; b_addr = 3'd0;
        sum_bank = 2'd0; sum_addr = 3'd0; diff_bank = 2'd0; diff_addr = 3'd0;
        case (phase)
{chr(10).join(lines)}
            default: ;
        endcase
    end
endmodule
"""


def ctrl_verilog(sch: Schedule) -> str:
    hdr = HEADER.format(name="dct8_ctrl.v -- distributed controller (four phase decoders)",
                        lat=sch.mr_lat, t0=sch.t0, rows=_rows(sch))
    mr_lines = []
    for r in sch.table:
        parts = []
        mi, md = r["mr_issue"], r["mr_done"]
        if mi:
            (_, ra), (_, rb) = mi["src"]
            parts.append(f"issue = 1'b1; k = 2'd{mi['k']}; a_addr = 3'd{ra}; b_addr = 3'd{rb};"
                         f"  // {mi['op']}: rotate ({mi['ins'][0]}, {mi['ins'][1]}) by {mi['k']}*pi/16")
        if md:
            (bu, ru), (bv, rv) = md["dst"]
            assert bu == bv
            parts.append(f"done = 1'b1; dst_ob = 1'b{int(bu == 'OB')}; u_addr = 3'd{ru};"
                         f" v_addr = 3'd{rv};  // {md['op']} -> ({md['outs'][0]}, {md['outs'][1]})")
        body = "\n                ".join(parts) if parts else "; // idle"
        mr_lines.append(f"            3'd{r['phase']}: begin\n                {body}\n            end")
    mr_mod = f"""
// Central CORDIC unit: issue (stage A) and completion (stage B, one clock later).
module dct8_ctrl_mr (
    input  wire [2:0] phase,
    output reg        issue,      // a rotation enters stage A
    output reg  [1:0] k,          // angle: k*pi/16, k = 1..3
    output reg  [2:0] a_addr,     // memory-bank addresses of the operands
    output reg  [2:0] b_addr,
    output reg        done,       // stage B writes a result pair
    output reg        dst_ob,     // 1: output buffer, 0: memory bank
    output reg  [2:0] u_addr,
    output reg  [2:0] v_addr
);
    always @(*) begin
        issue = 1'b0; k = 2'd1; a_addr = 3'd0; b_addr = 3'd0;
        done = 1'b0; dst_ob = 1'b0; u_addr = 3'd0; v_addr = 3'd0;
        case (phase)
{chr(10).join(mr_lines)}
            default: ;
        endcase
    end
endmodule
"""
    io_lines = []
    for r in sch.table:
        ibw = (f"ib_we = 1'b1;  // x{r['phase']} waits one clock for its partner"
               if r["ib_w"] is not None else "ib_we = 1'b0;")
        io_lines.append(f"            3'd{r['phase']}: begin\n                {ibw}\n"
                        f"                ob_raddr = 3'd{r['ob_r']}; out_k = 3'd{r['out_k']};"
                        f"  // read Y{r['out_k']}\n            end")
    io_mod = f"""
// Input buffer and rearrange (output) unit: in-order read-out of Y0..Y7.
module dct8_ctrl_io (
    input  wire [2:0] phase,
    output reg        ib_we,
    output reg  [2:0] ob_raddr,
    output reg  [2:0] out_k,      // index of the coefficient read this cycle
    output wire       out_start   // Y0 of a block is read this cycle
);
    assign out_start = (phase == 3'd{sch.out_phase});
    always @(*) begin
        ib_we = 1'b0; ob_raddr = 3'd0; out_k = 3'd0;
        case (phase)
{chr(10).join(io_lines)}
            default: ;
        endcase
    end
endmodule
"""
    return hdr + _bf_module(sch, 0) + _bf_module(sch, 1) + mr_mod + io_mod


def params_vh(sch: Schedule) -> str:
    return f"""// ============================================================================
// dct8_sched_params.vh -- GENERATED by `python -m dct8 emit`; do not edit.
// Included inside module bodies.
// ============================================================================
localparam SCHED_T0        = {sch.t0};   // Y0 is read from the output buffer T0 clocks after x0
localparam SCHED_OUT_PHASE = {sch.out_phase};    // phase in which Y0 of a block is read
localparam SCHED_OUT_BLOCK = {sch.out_block_offset};    // output window lags its input block by this many blocks
localparam SCHED_MR_LAT    = {sch.mr_lat};    // central CORDIC unit pipeline depth
localparam SCHED_BM_WORDS  = {sch.nregs['BM']};    // butterfly buffers (M_B)
localparam SCHED_MM_WORDS  = {sch.nregs['MM']};    // memory bank (CORDIC operands)
localparam SCHED_OB_WORDS  = {sch.nregs['OB']};    // output buffer (rearrange unit)
"""


def hls_header(sch: Schedule) -> str:
    def arr(name, vals, ctype="unsigned char"):
        return f"static const {ctype} {name}[8] = {{{', '.join(str(int(v)) for v in vals)}}};"
    rows = []
    for u in (0, 1):
        ops = [r["bf"][u] for r in sch.table]
        rows.append(f"// butterfly datapath BF{u}")
        rows.append(arr(f"BF{u}_EN", [1 if o else 0 for o in ops]))
        rows.append(arr(f"BF{u}_STAGE", [o["stage"] if o else 1 for o in ops]))
        if u == 0:
            rows.append(arr("BF0_A_IB", [int(o is not None and o["src"][0][0] == "IB") for o in ops]))
            rows.append(arr("BF0_B_IN", [int(o is not None and o["src"][1][0] == "IN") for o in ops]))
        rows.append(arr(f"BF{u}_A_ADDR", [(o["src"][0][1] or 0) if o else 0 for o in ops]))
        rows.append(arr(f"BF{u}_B_ADDR", [(o["src"][1][1] or 0) if o else 0 for o in ops]))
        rows.append(arr(f"BF{u}_SUM_BANK", [BANK_CODE[o["dst"][0][0]] if o else 0 for o in ops]))
        rows.append(arr(f"BF{u}_SUM_ADDR", [o["dst"][0][1] if o else 0 for o in ops]))
        rows.append(arr(f"BF{u}_DIFF_BANK", [BANK_CODE[o["dst"][1][0]] if o else 0 for o in ops]))
        rows.append(arr(f"BF{u}_DIFF_ADDR", [o["dst"][1][1] if o else 0 for o in ops]))
    mi = [r["mr_issue"] for r in sch.table]
    md = [r["mr_done"] for r in sch.table]
    rows.append("// central CORDIC unit")
    rows.append(arr("MR_ISSUE", [1 if m else 0 for m in mi]))
    rows.append(arr("MR_K", [m["k"] if m else 1 for m in mi]))
    rows.append(arr("MR_A_ADDR", [m["src"][0][1] if m else 0 for m in mi]))
    rows.append(arr("MR_B_ADDR", [m["src"][1][1] if m else 0 for m in mi]))
    rows.append(arr("MR_DONE", [1 if m else 0 for m in md]))
    rows.append(arr("MR_DST_OB", [int(m["dst"][0][0] == "OB") if m else 0 for m in md]))
    rows.append(arr("MR_U_ADDR", [m["dst"][0][1] if m else 0 for m in md]))
    rows.append(arr("MR_V_ADDR", [m["dst"][1][1] if m else 0 for m in md]))
    rows.append("// input buffer and rearrange unit")
    rows.append(arr("IB_WE", [1 if r["ib_w"] is not None else 0 for r in sch.table]))
    rows.append(arr("OB_RADDR", [r["ob_r"] for r in sch.table]))
    rows.append(arr("OUT_K", [r["out_k"] for r in sch.table]))
    body = "\n".join(rows)
    return f"""// ============================================================================
// dct8_sched.h -- GENERATED by `python -m dct8 emit`; do not edit.
// Per-phase microcode of the memory-based processor (same as rtl/dct8_ctrl.v).
// ============================================================================
#ifndef DCT8_SCHED_H
#define DCT8_SCHED_H

#define SCHED_T0        {sch.t0}
#define SCHED_OUT_PHASE {sch.out_phase}
#define SCHED_OUT_BLOCK {sch.out_block_offset}
#define SCHED_BM_WORDS  {sch.nregs['BM']}
#define SCHED_MM_WORDS  {sch.nregs['MM']}
#define SCHED_OB_WORDS  {sch.nregs['OB']}
#define BANK_BM 0
#define BANK_MM 1
#define BANK_OB 2

{body}

#endif
"""


def write(root: str | Path, mr_lat: int = schedule.DEFAULT_MR_LAT) -> Schedule:
    root = Path(root)
    for d in ("rtl", "hls/src", "vectors"):
        (root / d).mkdir(parents=True, exist_ok=True)
    sch = schedule.build(mr_lat)
    (root / "rtl" / "dct8_ctrl.v").write_text(ctrl_verilog(sch))
    (root / "rtl" / "dct8_sched_params.vh").write_text(params_vh(sch))
    (root / "hls" / "src" / "dct8_sched.h").write_text(hls_header(sch))
    (root / "vectors" / "schedule.json").write_text(sch.to_json() + "\n")
    return sch
